check (const char *name, const char *value, const char *expected)
{
	GString *s = g_string_new (NULL);
	append_param_quoted (s, name, value);
	printf ("name='%s' value='%s' -> '%s' expected '%s' %s\n",
		name, value, s->str, expected,
		strcmp (s->str, expected) == 0 ? "PASS" : "FAIL");
	if (strcmp (s->str, expected) != 0)
		failures++;
	g_string_free (s, TRUE);
}

int
main (void)
{
	check ("x", "abc", "x=\"abc\"");
